export async function createScene(engine, canvas, BABYLON) {
  var scene = new BABYLON.Scene(engine);

  let myMeshes = [];
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "pizza.glb" });
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "waffle.glb" });
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "taco.glb" });
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "tacoyaki.glb" });
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "hotdog.glb" });
  myMeshes.push({ rootUrl: "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", filename: "hamburger.glb" });

  let plane1 = createPlane(BABYLON.Vector3.Backward(), 1);
  let plane2 = createPlane(BABYLON.Vector3.Right(), 2);
  let plane3 = createPlane(BABYLON.Vector3.Up(), 3);
  let plane4 = createPlane(BABYLON.Vector3.Down(), 4);
  let plane5 = createPlane(BABYLON.Vector3.Left(), 5);
  let plane6 = createPlane(BABYLON.Vector3.Forward(), 6);

  let dirLight = new BABYLON.DirectionalLight("", new BABYLON.Vector3(1, -3, 1));
  dirLight.intensity = 4;

  for (let i = 0; i < 6; i++) {
    let color = BABYLON.Color3.Random();

    let box2 = BABYLON.MeshBuilder.CreateBox(`box_2${i}`, { size: 2, sideOrientation: 1 });
    let mat2 = new BABYLON.PBRMaterial("mat${i}");
    mat2.stencil.enabled = true;
    mat2.stencil.funcRef = i + 1;
    mat2.stencil.func = BABYLON.Engine.EQUAL;

    mat2.albedoColor = color;
    mat2.metallic = 0;
    mat2.roughness = 1;
    box2.material = mat2;
    box2.receiveShadows = true;

    BABYLON.SceneLoader.ImportMeshAsync("", myMeshes[i].rootUrl, myMeshes[i].filename).then((e) => {
      let { meshes } = e;
      meshes[0].name = myMeshes[i].filename;

      meshes.forEach((e) => {
        let mat = e.material;
        if (mat) {
          mat.stencil.enabled = true;
          mat.stencil.funcRef = i + 1;
          mat.stencil.func = BABYLON.Engine.EQUAL;
        }
      });
      let { min, max } = meshes[0].getHierarchyBoundingVectors();
      let center = max.add(min).scale(0.5);
      let scale = BABYLON.Vector3.One().divide(max.subtract(min));
      let sm = Math.min(scale.x, Math.min(scale.y, scale.z));
      meshes[0].scaling.scaleInPlace(sm * 1.5);

      meshes[0].position = center.scale(-1);

      if (i === 0) {
        meshes[0].position.y = -0.2;
      }
      if (i === 3) {
        meshes[0].rotation = new BABYLON.Vector3(Math.PI, Math.PI, 0);
      }
      if (i === 5) {
        meshes[0].position.y = -0.6;
      }
    });
  }

  scene.createDefaultCamera(1, 1, 1);

  let camera = scene.activeCamera;
  camera.alpha = -2.338;
  camera.beta = 0.966;

  scene.createDefaultEnvironment({ createGround: false, createSkybox: false });
  scene.environmentIntensity = 1;

  function hsvToRgb(h, s, v) {
    const i = Math.floor(h * 6);
    const f = h * 6 - i;
    const p = v * (1 - s);
    const q = v * (1 - f * s);
    const t = v * (1 - (1 - f) * s);
    const mod = i % 6;

    const r = [v, q, p, p, t, v][mod];
    const g = [t, v, v, q, p, p][mod];
    const b = [p, p, t, v, v, q][mod];

    return new BABYLON.Color3(r, g, b);
  }

  scene.registerBeforeRender(() => {
    const t = performance.now() * 0.00005;
    const hue = t % 1;
    const rgb = hsvToRgb(hue, 0.6, 1.0);
    scene.clearColor = new BABYLON.Color4(rgb.r, rgb.g, rgb.b, 1.0);
  });

  function createPlane(dir, ref) {
    let plane = BABYLON.MeshBuilder.CreatePlane(`${ref}`, { size: 2 });
    plane.lookAt(dir.negate());
    plane.position.addInPlace(dir);

    let mat = new BABYLON.StandardMaterial(`${ref}`);
    plane.material = mat;
    mat.stencil.enabled = true;
    mat.stencil.funcRef = ref;
    mat.disableDepthWrite = true;
    mat.disableColorWrite = true;
  }

  return scene;
}
